  'admin/addon/add_tip' => '提示：<br>
                1.僅支援 zip；識別名稱須為小寫字母開頭（a-z0-9_）。<br>
                2.包內禁止 ../、寫入系統目錄，以及 .phtml/.htaccess 等高風險檔案。<br>
                3.安裝後預設停用，請在外掛列表中手動啟用。<br>
                4.簽名預設不強制：未設定 addon.require_local_signature=1 時，無簽名 zip 仍可安裝（安裝外掛即執行 PHP）。正式環境建議開啟強制驗簽並配置公鑰；亦可在包內附帶 package.manifest.json + package.sig（RS256，有材料則必驗）。<br>
                5.請只安裝可信來源外掛，並事先備份網站。',
