  'admin/database/sql' => '執行sql語句',
  'admin/database/sql_tip' => '常用語句對照：<br>
                        1.查詢數據
                        SELECT * FROM {pre}vod   查詢所有數據<br>
                        SELECT * FROM {pre}vod WHERE vod_id=1000   查詢指定ID數據
                        <br>
                        2.刪除數據
                        DELETE FROM {pre}vod   刪除所有數據<br>
                        DELETE FROM {pre}vod WHERE vod_id=1000   刪除指定的第幾條數據<br>
                        DELETE FROM {pre}vod WHERE vod_actor LIKE \'%劉德華%\'   vod_actor"劉德華"的數據
                        <br>
                        3.修改數據
                        UPDATE {pre}vod SET vod_hits=1   將所有vod_hits字段裏的值修改成"1"<br>
                        UPDATE {pre}vod SET vod_hits=1 WHERE vod_id=1000  指定的第幾條數據把vod_hits字段裏的值修改成"1"
                        <br>
                        4.替換圖片地址
                        UPDATE {pre}vod SET vod_pic=REPLACE(vod_pic, \'原始字符串\', \'替換成其他字符串\')
                        <br>
                        5.清空數據ID重新從1開始
                        TRUNCATE {pre}vod',
  'admin/safety/data_inspect' => '掛馬檢測',
  'admin/safety/data_inspect_tip' => '<strong>掛馬檢測3.0版本</strong><br>
                            1，將對分類表，視頻表，文章表，會員表等表結構進行檢查。<br>
                            2，檢測包含script,iframe等特殊字符串。<br>
                            3，將自動清除掛馬代碼。<br>
                            4，不能保證100%清除，如還有問題請自行進入phpmyadmin或其他數據庫管理工具裏清除。<br>
                            5，建議清理多次，直到沒有出現問題數據。',
